                    class="product__description rte quick-add-hidden product-copy"
                    data-product-description
                    {{ block.shopify_attributes }}
                  >
                    {% render 'optimized-product-description', description_html: product.description %}
                  </div>
                {%- endif -%}
                {% render 'product-internal-links', product: product %}
              {%- when 'sku' -%}
                <p
                  class="product__sku{% if block.settings.text_style == 'uppercase' %} caption-with-letter-spacing{% elsif block.settings.text_style == 'subtitle' %} subtitle{% endif %}{% if product.selected_or_first_available_variant.sku.size == 0 %} visibility-hidden{% endif %}"
                  id="Sku-{{ section.id }}"
                  role="status"
                  {{ block.shopify_attributes }}
                >
                  <span class="visually-hidden">{{ 'products.product.sku' | t }}:</span>
                  {{- product.selected_or_first_available_variant.sku -}}
                </p>
              {%- when 'custom_liquid' -%}
                {{ block.settings.custom_liquid }}
              {%- when 'collapsible_tab' -%}
                <div class="product__accordion accordion quick-add-hidden" {{ block.shopify_attributes }}>
                  <details id="Details-{{ block.id }}-{{ section.id }}">
                    <summary>
                      <div class="summary__title">
                        {% render 'icon-accordion', icon: block.settings.icon %}
                        <h2 class="h4 accordion__title inline-richtext">
                          {{ block.settings.heading | default: block.settings.page.title | escape }}
                        </h2>
                      </div>
                      {% render 'icon-caret' %}
                    </summary>
                    <div class="accordion__content rte" id="ProductAccordion-{{ block.id }}-{{ section.id }}">
                      {{ block.settings.content }}
                      {{ block.settings.page.content }}
                    </div>
                  </details>
                </div>
              {%- when 'quantity_selector' -%}
                <div
                  id="Quantity-Form-{{ section.id }}"
                  class="product-form__input product-form__quantity{% if settings.inputs_shadow_vertical_offset != 0 and settings.inputs_shadow_vertical_offset < 0 %} product-form__quantity-top{% endif %}"
                  {{ block.shopify_attributes }}
                >
                  {% comment %} TODO: enable theme-check once `item_count_for_variant` is accepted as valid filter {% endcomment %}
                  {% # theme-check-disable %}
                  {%- assign cart_qty = cart
                    | item_count_for_variant: product.selected_or_first_available_variant.id
                  -%}
                  {% # theme-check-enable %}
                  <label class="quantity__label form__label" for="Quantity-{{ section.id }}">
                    {{ 'products.product.quantity.label' | t }}
                    <span class="quantity__rules-cart{% if cart_qty == 0 %} hidden{% endif %}">
                      {%- render 'loading-spinner' -%}
                      <span
                        >(
                        {{- 'products.product.quantity.in_cart_html' | t: quantity: cart_qty -}}
                        )</span
                      >
                    </span>
                  </label>
                  <div class="price-per-item__container">
                    <quantity-input class="quantity" data-url="{{ product.url }}" data-section="{{ section.id }}">
                      <button class="quantity__button" name="minus" type="button">
                        <span class="visually-hidden">
                          {{- 'products.product.quantity.decrease' | t: product: product.title | escape -}}
                        </span>
                        {% render 'icon-minus' %}
                      </button>
                      <input
                        class="quantity__input"
                        type="number"
                        name="quantity"
                        id="Quantity-{{ section.id }}"
                        data-cart-quantity="{{ cart_qty }}"
                        data-min="{{ product.selected_or_first_available_variant.quantity_rule.min }}"
                        min="{{ product.selected_or_first_available_variant.quantity_rule.min }}"
                        {% if product.selected_or_first_available_variant.quantity_rule.max != null %}
                          data-max="{{ product.selected_or_first_available_variant.quantity_rule.max }}"
                          max="{{ product.selected_or_first_available_variant.quantity_rule.max }}"
                        {% endif %}
                        step="{{ product.selected_or_first_available_variant.quantity_rule.increment }}"
                        value="{{ product.selected_or_first_available_variant.quantity_rule.min }}"
                        form="{{ product_form_id }}"
                      >
                 <button class="quantity__button" name="plus" type="button">
    <span class="visually-hidden">
        {{- 'products.product.quantity.increase' | t: product: product.title | escape -}}
    </span>
    {% render 'icon-plus' %}
</button>
                    </quantity-input>

                    {%- if has_matching_set_context and product.has_only_default_variant == false -%}
                      <p class="product-form__matching-set-hint">
                        {{ 'products.product.matching_set.copy' | t }}
                      </p>
                    {%- endif -%}





                    {%- liquid
                      assign volume_pricing_array = product.selected_or_first_available_variant.quantity_price_breaks | sort: 'quantity' | reverse
                      assign current_qty_for_volume_pricing = cart_qty | plus: product.selected_or_first_available_variant.quantity_rule.min
                      if cart_qty > 0
                        assign current_qty_for_volume_pricing = cart_qty | plus: product.selected_or_first_available_variant.quantity_rule.increment
                      endif
                    -%}
                    {%- if product.quantity_price_breaks_configured? -%}
                      <price-per-item
                        id="Price-Per-Item-{{ section.id }}"
                        data-section-id="{{ section.id }}"
                        data-variant-id="{{ product.selected_or_first_available_variant.id }}"
                      >
                        {%- if product.selected_or_first_available_variant.quantity_price_breaks.size > 0 -%}
                          {%- assign variant_price_compare = product.selected_or_first_available_variant.compare_at_price -%}
                          <div class="price-per-item">
                            {%- if variant_price_compare -%}
                              <dl class="price-per-item--current">
                                <dt class="visually-hidden">
                                  {{ 'products.product.price.regular_price' | t }}
                                </dt>
                                <dd>
                                  <s class="variant-item__old-price">
                                    {{ variant_price_compare | money_with_currency }}
                                  </s>
                                </dd>
                              </dl>
                            {%- endif -%}
                            {%- if current_qty_for_volume_pricing < volume_pricing_array.last.minimum_quantity -%}
                              {%- assign variant_price = product.selected_or_first_available_variant.price
                                | money_with_currency
                              -%}
                              <span class="price-per-item--current">
                                {{- 'products.product.volume_pricing.price_at_each' | t: price: variant_price -}}
                              </span>
                            {%- else -%}
                              {%- for price_break in volume_pricing_array -%}
                                {%- if current_qty_for_volume_pricing >= price_break.minimum_quantity -%}
                                  {%- assign price_break_price = price_break.price | money_with_currency -%}
                                  <span class="price-per-item--current">
                                    {{-
                                      'products.product.volume_pricing.price_at_each'
                                      | t: price: price_break_price
                                    -}}
                                  </span>
                                  {%- break -%}
                                {%- endif -%}
                              {%- endfor -%}
                            {%- endif -%}
                          </div>
                        {%- else -%}
                          {%- assign variant_price = product.selected_or_first_available_variant.price
                            | money_with_currency
                          -%}
                          {%- assign variant_price_compare = product.selected_or_first_available_variant.compare_at_price -%}
                          <div class="price-per-item">
                            {%- if variant_price_compare -%}
                              <dl class="price-per-item--current">
                                <dt class="visually-hidden">
                                  {{ 'products.product.price.regular_price' | t }}
                                </dt>
                                <dd>
                                  <s class="variant-item__old-price">
                                    {{ variant_price_compare | money_with_currency }}
                                  </s>
                                </dd>
                                <dt class="visually-hidden">
                                  {{ 'products.product.price.sale_price' | t }}
                                </dt>
                                <dd>
                                  <span class="price-per-item--current">
                                    {{- 'products.product.volume_pricing.price_at_each' | t: price: variant_price -}}
                                  </span>
                                </dd>
                              </dl>
                            {%- else -%}
                              <span class="price-per-item--current">
                                {{- 'products.product.volume_pricing.price_at_each' | t: price: variant_price -}}
                              </span>
                            {%- endif -%}
                          </div>
                        {%- endif -%}
                      </price-per-item>
                    {%- endif -%}
                  </div>
                  <div class="quantity__rules caption" id="Quantity-Rules-{{ section.id }}">
                    {%- if product.selected_or_first_available_variant.quantity_rule.increment > 1 -%}
                      <span class="divider">
                        {{-
                          'products.product.quantity.multiples_of'
                          | t: quantity: product.selected_or_first_available_variant.quantity_rule.increment
                        -}}
                      </span>
                    {%- endif -%}
                    {%- if product.selected_or_first_available_variant.quantity_rule.min > 1 -%}
                      <span class="divider">
                        {{-
                          'products.product.quantity.minimum_of'
                          | t: quantity: product.selected_or_first_available_variant.quantity_rule.min
                        -}}
                      </span>
                    {%- endif -%}
                    {%- if product.selected_or_first_available_variant.quantity_rule.max != null -%}
                      <span class="divider">
                        {{-
                          'products.product.quantity.maximum_of'
                          | t: quantity: product.selected_or_first_available_variant.quantity_rule.max
                        -}}
                      </span>
                    {%- endif -%}
                  </div>
                  {%- if product.quantity_price_breaks_configured? -%}
                    <volume-pricing class="parent-display" id="Volume-{{ section.id }}">
                      {%- if product.selected_or_first_available_variant.quantity_price_breaks.size > 0 -%}
                        <span class="caption-large">{{ 'products.product.volume_pricing.title' | t }}</span>
                        <ul class="list-unstyled">
                          <li>
                            <span>{{ product.selected_or_first_available_variant.quantity_rule.min }}+</span>
                            {%- assign price = product.selected_or_first_available_variant.price
                              | money_with_currency
                            -%}
                            <span data-text="{{ 'products.product.volume_pricing.price_at_each' | t: price: variant_price }}">
                              {{- 'sections.quick_order_list.each' | t: money: price -}}
                            </span>
                          </li>
                          {%- for price_break in product.selected_or_first_available_variant.quantity_price_breaks -%}
                            {%- assign price_break_price = price_break.price | money_with_currency -%}
                            <li class="{%- if forloop.index >= 3 -%}show-more-item hidden{%- endif -%}">
                              <span>
                                {{- price_break.minimum_quantity -}}
                                <span aria-hidden="true">+</span></span
                              >
                              <span data-text="{{ 'products.product.volume_pricing.price_at_each' | t: price: price_break_price }}">
                                {{- 'sections.quick_order_list.each' | t: money: price_break_price -}}
                              </span>
                            </li>
                          {%- endfor -%}
                        </ul>
                        {%- if product.selected_or_first_available_variant.quantity_price_breaks.size >= 3 -%}
                          <show-more-button>
                            <button
                              class="button-show-more link underlined-link"
                              id="Show-More-{{ section.id }}"
                              type="button"
                            >
                              <span class="label-show-more label-text"
                                ><span aria-hidden="true">+ </span>{{ 'products.facets.show_more' | t }}
                              </span>
                            </button>
                          </show-more-button>
                        {%- endif -%}
                      {%- endif -%}
                    </volume-pricing>
                  {%- endif -%}
                </div>
              {%- when 'popup' -%}
                <modal-opener
                  class="product-popup-modal__opener quick-add-hidden"
                  data-modal="#PopupModal-{{ block.id }}"
                  {{ block.shopify_attributes }}
                >
                  <button
                    id="ProductPopup-{{ block.id }}"
                    class="product-popup-modal__button link"
                    type="button"
                    aria-haspopup="dialog"
                  >
                    {{ block.settings.text | default: block.settings.page.title | escape }}
                  </button>
                </modal-opener>


              {%- when 'share' -%}
                {% liquid
                  assign share_url = product.selected_variant.url | default: product.url | prepend: request.origin
                  render 'share-button', block: block, share_link: share_url
                %}

              {%- when 'variant_picker' -%}
                {% render 'product-variant-picker', product: product, block: block, product_form_id: product_form_id %}
              {%- when 'buy_buttons' -%}
                {%- render 'buy-buttons',
                  block: block,
                  product: product,
                  product_form_id: product_form_id,
                  section_id: section.id,
                  show_pickup_availability: true,
                  has_matching_set_context: has_matching_set_context,
                  hide_trust_strip: true
                -%}
                {% render 'product-desktop-ux', product: product, section: section %}

                {%- comment -%}
                  Dropshipping guardrail: do not create shopper urgency from
                  Shopify inventory counts. Channel/feed inventory is a
                  salability signal here, not proof of owned local stock.
                {%- endcomment -%}

                {%- comment -%}
                  CRO: removed above-the-fold trust strip — it duplicated the "Shipping & Delivery"
                  collapsible directly below it (same country, arrival window, and "Standard shipping
                  included" copy). Kept the collapsible as the single source of truth; the "Free"
                  wording in `free_shipping_label` and `product_note_html` makes it clear shoppers
                  pay nothing extra for standard shipping.
                {%- endcomment -%}

<!-- Purchase Confidence module -->
<div class="additional-info">
  {%- liquid
    assign shipping_label_copy = 'products.additional_info.free_shipping_label' | t
    assign delivery_estimate_copy = 'products.additional_info.estimated_delivery' | t
    assign standard_delivery_window = 'products.additional_info.standard_delivery_window' | t
    assign premium_delivery_window = 'products.additional_info.premium_delivery_window' | t

    if shipping_label_copy == blank or shipping_label_copy contains 'translation missing'
      assign shipping_label_copy = 'Standard shipping included'
    endif
    if delivery_estimate_copy == blank or delivery_estimate_copy contains 'translation missing'
      assign delivery_estimate_copy = 'Estimated delivery:'
    endif
    if standard_delivery_window == blank or standard_delivery_window contains 'translation missing' or standard_delivery_window contains 'business days'
      # CRO: standardized 12-16 calendar-day window for the PDP Purchase
      # Confidence card. Calendar mode is enabled on #dlm-shipping-card-date
      # so the displayed date range is identical across all countries.
      assign standard_delivery_window = '12-16 days'
    endif
    if premium_delivery_window contains 'translation missing' or premium_delivery_window contains '5-7 business days' or premium_delivery_window == blank
      assign premium_delivery_window = ''
    endif

    assign standard_delivery_copy = delivery_estimate_copy | append: ' ' | append: standard_delivery_window
  -%}
  {%- comment -%}
    CRO (Baymard-aligned): consolidated Shipping, Returns, and Shopping
    Security into ONE Purchase Confidence module — three promise-first
    summary rows + three collapsed <details>. Replaces the previous
    delivery-promise card and the two auto-expanded accordions.

    Principle: show the promise first, hide the policy detail until
    requested. Chevron icons (▾) make it obvious the details are
    expandable; "X"-style toggles are gone.
  {%- endcomment -%}
  {% render 'pdp-purchase-confidence',
     shipping_label_copy: shipping_label_copy,
     delivery_estimate_copy: delivery_estimate_copy,
     standard_delivery_window: standard_delivery_window,
     standard_delivery_copy: standard_delivery_copy %}

  {%- comment -%}
    CRO: in-page modals for "View return details" and "View privacy details".
    The triggers inside pdp-purchase-confidence keep their real /policies/...
    hrefs, so right-click "open in new tab", SEO crawlers, and no-JS users
    still reach the full policy pages — JS only intercepts a plain left
    click to open a lightweight modal instead, keeping shoppers on the PDP.
  {%- endcomment -%}
  {% render 'pdp-policy-modals' %}

  {%- comment -%}
    CRO Step 7: rewrite apologetic / merchant-y phrases inside the
    rendered product description on the live DOM. Lets live shoppers
    see clean copy immediately while the underlying product
    descriptions are updated in Shopify Admin.
  {%- endcomment -%}
  {% render 'pdp-description-copy-cleanup' %}

  {%- comment -%} Hidden premium-tier row — surfaced by JS if/when an express rate is configured. {%- endcomment -%}
  <p style="margin:6px 0 0;color:#374151;font-size:0.92em;" data-delivery-estimate-row data-delivery-estimate-tier="premium" hidden>{{ 'products.additional_info.faster_shipping_prefix' | t }} <strong><span id="ups-delivery-date" data-delivery-window="{{ premium_delivery_window | escape }}" data-delivery-fallback="{{ premium_delivery_window | escape }}"></span></strong></p>
</div>



              {%- when 'rating' -%}
                {%- liquid
                  assign rating_count_raw = product.metafields.reviews.rating_count.value | default: product.metafields.reviews.rating_count
                  assign rating_count_int = rating_count_raw | plus: 0
                -%}
                {%- if product.metafields.reviews.rating.value != blank and rating_count_int > 0 -%}
                  <div class="rating-wrapper">
                    {% liquid
                      assign rating_decimal = 0
                      assign decimal = product.metafields.reviews.rating.value.rating | modulo: 1
                      if decimal >= 0.3 and decimal <= 0.7
                        assign rating_decimal = 0.5
                      elsif decimal > 0.7
                        assign rating_decimal = 1
                      endif
                    %}
                    <div
                      class="rating"
                      role="img"
                      aria-label="{{ 'accessibility.star_reviews_info' | t: rating_value: product.metafields.reviews.rating.value, rating_max: product.metafields.reviews.rating.value.scale_max }}"
                    >
                      <span
                        aria-hidden="true"
                        class="rating-star"
                        style="--rating: {{ product.metafields.reviews.rating.value.rating | floor }}; --rating-max: {{ product.metafields.reviews.rating.value.scale_max }}; --rating-decimal: {{ rating_decimal }};"
                      ></span>
                    </div>
                    <p class="rating-text caption">
                      <span aria-hidden="true">
                        {{- product.metafields.reviews.rating.value }} /
                        {{ product.metafields.reviews.rating.value.scale_max -}}
                      </span>
                    </p>
                    <p class="rating-count caption">
                      <span aria-hidden="true">({{ product.metafields.reviews.rating_count }})</span>
                      <span class="visually-hidden">
                        {{- product.metafields.reviews.rating_count }}
                        {{ 'accessibility.total_reviews' | t -}}
                      </span>
                    </p>
                  </div>
                {%- endif -%}
              {%- when 'complementary' -%}
                {%- unless has_family_sets_context -%}
                  <product-recommendations
                    class="complementary-products quick-add-hidden{% if block.settings.make_collapsible_row %} is-accordion{% endif %}{% if block.settings.enable_quick_add %} complementary-products-contains-quick-add{% endif %}"
                    data-url="{{ routes.product_recommendations_url }}?section_id={{ section.id }}&product_id={{ product.id }}&limit={{ block.settings.product_list_limit }}&intent=complementary"
                  >
                    {%- if recommendations.performed and recommendations.products_count > 0 -%}
                      <aside
                        aria-label="{{ 'accessibility.complementary_products' | t }}"
                        {{ block.shopify_attributes -}}
                        {% if block.settings.make_collapsible_row %}
                          class="product__accordion accordion"
                        {% endif %}
                      >
                        <div class="complementary-products__container">
                          {%- if block.settings.make_collapsible_row -%}
                            <details id="Details-{{ block.id }}-{{ section.id }}" open>
                              <summary>
                          {%- endif %}
                          <div class="summary__title">
                            {%- if block.settings.make_collapsible_row -%}
                              {% render 'icon-accordion', icon: block.settings.icon %}
                              <h2 class="h4 accordion__title">{{ block.settings.block_heading }}</h2>
                            {%- else -%}
                              <h2 class="h3 accordion__title">{{ block.settings.block_heading }}</h2>
                            {%- endif -%}
                          </div>
                          {%- if block.settings.make_collapsible_row -%}
                            {% render 'icon-caret' %}
                            </summary>
                          {%- endif -%}
                          <slideshow-component class="slider-mobile-gutter">
                            {%- assign number_of_slides = recommendations.products_count
                              | plus: 0.0
                              | divided_by: block.settings.products_per_page
                              | ceil
                            -%}
                            <div
                              id="Slider-{{ block.id }}"
                              class="contains-card contains-card--product complementary-slider grid grid--1-col slider slider--everywhere"
                              role="list"
                              {% if number_of_slides > 1 %}
                                aria-label="{{ 'general.slider.name' | t }}"
                              {% endif %}
                            >
                              {%- for i in (1..number_of_slides) -%}
                                <div
                                  id="Slide-{{ block.id }}-{{ forloop.index }}"
                                  class="complementary-slide complementary-slide--{{ settings.card_style }} grid__item slider__slide slideshow__slide"
                                  tabindex="-1"
                                  role="group"
                                  {% if number_of_slides > 1 %}
                                    aria-roledescription="{{ 'sections.slideshow.slide' | t }}"
                                    aria-label="{{ forloop.index }} {{ 'general.slider.of' | t }} {{ forloop.length }}"
                                  {% endif %}
                                >
                                  <ul class="list-unstyled" role="list">
                                    {% comment %}theme-check-disable UndefinedObject{% endcomment %}
                                    {%- for product in recommendations.products
                                      limit: block.settings.products_per_page
                                      offset: continue
                                    -%}
                                      {% comment %}theme-check-enable UndefinedObject{% endcomment %}
                                      <li>
                                        {%- if block.settings.enable_quick_add -%}
                                          {% assign quick_add = "standard" %}
                                        {%- else -%}
                                          {% assign quick_add = "none" %}
                                        {%- endif -%}
                                        {% render 'card-product',
                                          card_product: product,
                                          media_aspect_ratio: block.settings.image_ratio,
                                          show_secondary_image: false,
                                          lazy_load: false,
                                          quick_add: quick_add,
                                          section_id: section.id,
                                          horizontal_class: true,
                                          horizontal_quick_add: true
                                        %}
                                      </li>
                                    {%- endfor -%}
                                  </ul>
                                </div>
                              {%- endfor -%}
                            </div>
                            {%- if number_of_slides > 1 -%}
                              <div class="slider-buttons">
                                <button
                                  type="button"
                                  class="slider-button slider-button--prev"
                                  name="previous"
                                  aria-label="{{ 'general.slider.previous_slide' | t }}"
                                >
                                  {% render 'icon-caret' %}
                                </button>
                                <div class="slider-counter slider-counter--{{ block.settings.pagination_style }}{% if block.settings.pagination_style == 'counter' or block.settings.pagination_style == 'numbers' %} caption{% endif %}">
                                  {%- if block.settings.pagination_style == 'counter' -%}
                                    <span class="slider-counter--current">1</span>
                                    <span aria-hidden="true"> / </span>
                                    <span class="visually-hidden">{{ 'general.slider.of' | t }}</span>
                                    <span class="slider-counter--total">{{ number_of_slides }}</span>
                                  {%- else -%}
                                    <div class="slideshow__control-wrapper">
                                      {%- for i in (1..number_of_slides) -%}
                                        <button
                                          class="slider-counter__link slider-counter__link--{{ block.settings.pagination_style }} link"
                                          aria-label="{{ 'sections.slideshow.load_slide' | t }} {{ forloop.index }} {{ 'general.slider.of' | t }} {{ forloop.length }}"
                                          aria-controls="Slider-{{ block.id }}"
                                        >
                                          {%- if block.settings.pagination_style == 'numbers' -%}
                                            {{ forloop.index -}}
                                          {%- else -%}
                                            <span class="dot"></span>
                                          {%- endif -%}
                                        </button>
                                      {%- endfor -%}
                                    </div>
                                  {%- endif -%}
                                </div>
                                <button
                                  type="button"
                                  class="slider-button slider-button--next"
                                  name="next"
                                  aria-label="{{ 'general.slider.next_slide' | t }}"
                                >
                                  {% render 'icon-caret' %}
                                </button>
                              </div>
                            {%- endif -%}
                          </slideshow-component>
                          {%- if block.settings.make_collapsible_row -%}
                            </details>
                          {%- endif -%}
                        </div>
                      </aside>
                    {%- endif -%}
                    {{ 'component-complementary-products.css' | asset_url | stylesheet_tag }}
                    {%- if block.settings.enable_quick_add -%}
                      {{ 'quick-add.css' | asset_url | stylesheet_tag }}
                      <script src="{{ 'quick-add.js' | asset_url }}" defer="defer"></script>
                    {%- endif -%}
                  </product-recommendations>
                {%- endunless -%}
              {%- when 'icon-with-text' -%}
                {% render 'icon-with-text', block: block %}
            {%- endcase -%}
          {%- endfor -%}
          <a href="{{ product.url }}" class="link product__view-details animate-arrow">
            {{ 'products.product.view_full_details' | t }}
            {% render 'icon-arrow' %}
          </a>
        </product-info>
        <script src="{{ 'product-description.js' | asset_url }}" defer="defer"></script>
      </div>
    </div>

    {% render 'product-media-modal', variant_images: variant_images %}

    {% assign popups = section.blocks | where: 'type', 'popup' %}
    {%- for block in popups -%}
      <modal-dialog id="PopupModal-{{ block.id }}" class="product-popup-modal" {{ block.shopify_attributes }}>
        <div
          role="dialog"
          aria-label="{{ block.settings.text }}"
          aria-modal="true"
          class="product-popup-modal__content"
          tabindex="-1"
        >
          <button
            id="ModalClose-{{ block.id }}"
            type="button"
            class="product-popup-modal__toggle"
            aria-label="{{ 'accessibility.close' | t }}"
          >
            {% render 'icon-close' %}
          </button>
          <div class="product-popup-modal__content-info">
            <h1 class="h2">{{ block.settings.page.title | escape }}</h1>
            {{ block.settings.page.content }}
          </div>
        </div>
      </modal-dialog>
    {%- endfor -%}

    {%- if product.media.size > 0 -%}
      <script src="{{ 'product-modal.js' | asset_url }}" defer="defer"></script>
      <script src="{{ 'media-gallery.js' | asset_url }}" defer="defer"></script>
    {%- endif -%}

    {%- if first_3d_model -%}
      <script type="application/json" id="ProductJSON-{{ product.id }}">
        {{ product.media | where: 'media_type', 'model' | json }}
      </script>
      <script src="{{ 'product-model.js' | asset_url }}" defer></script>
    {%- endif -%}

    <script type="application/json" id="ProductAnalyticsData-{{ section.id }}">
      {%- liquid
        assign product_public_brand = product.vendor | default: 'dresslikemommy.com' | strip
        assign product_public_brand_downcase = product_public_brand | downcase
        if product_public_brand == blank or product_public_brand_downcase contains 'http://' or product_public_brand_downcase contains 'https://' or product_public_brand_downcase contains '1688.com' or product_public_brand_downcase contains 'alibaba.com' or product_public_brand_downcase contains 'aliexpress.com'
          assign product_public_brand = 'dresslikemommy.com'
        endif
      -%}
      {
        "id": {{ product.id | json }},
        "handle": {{ product.handle | json }},
        "title": {{ product.title | json }},
        "vendor": {{ product_public_brand | json }},
        "currency": {{ cart.currency.iso_code | json }},
        "category1": {{ taxonomy_category1 | json }},
        "subcategory": {{ taxonomy_subcategory | json }},
        "subcategory2": {{ taxonomy_subcategory2 | json }},
        "type": {{ taxonomy_type | json }},
        "style": {{ taxonomy_style | json }},
        "pattern": {{ taxonomy_pattern | json }},
        "selected_variant_id": {{ product.selected_or_first_available_variant.id | json }},
        "variants": [
          {%- for variant in product.variants -%}
            {
              "id": {{ variant.id | json }},
              "title": {{ variant.title | json }},
              "sku": {{ variant.sku | json }},
              "barcode": {{ variant.barcode | json }},
              "price_cents": {{ variant.price | json }},
              "available": {{ variant.available | json }}
            }{% unless forloop.last %},{% endunless %}
          {%- endfor -%}
        ]
      }
    </script>
  </div>
</section>

{%- comment -%} Sticky mobile Add to Cart bar {%- endcomment -%}
{%- if product.available -%}
  {%- liquid
      assign sticky_free_shipping_label = 'products.product.free_shipping_short' | t
      if sticky_free_shipping_label == blank or sticky_free_shipping_label contains 'translation missing'
      assign sticky_free_shipping_label = 'Standard shipping included'
      endif
  -%}
  <div class="sticky-mobile-atc" id="StickyMobileATC-{{ section.id }}">
    <div class="sticky-mobile-atc__details" aria-live="polite" aria-atomic="true">
      <span class="sticky-mobile-atc__price" data-sticky-mobile-atc-price>
        {{- product.selected_or_first_available_variant.price | money -}}
      </span>
      {%- comment -%}
        CRO Step 6: standard-shipping reassurance on the sticky bar.
        Visible by default (when size/color are unconfirmed) so the
        shopper sees a benefit alongside the price. Hidden by JS once
        selections complete (the size chip + ATC price take over).
      {%- endcomment -%}
      <span class="sticky-mobile-atc__shipping" data-sticky-mobile-atc-shipping>
        <svg xmlns="http://www.w3.org/2000/svg" width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" style="vertical-align:-1px;margin-right:2px;"><polyline points="20 6 9 17 4 12"/></svg>{{ sticky_free_shipping_label }}
      </span>
      <span class="sticky-mobile-atc__size" data-sticky-mobile-atc-size hidden></span>
    </div>
    <button type="button" class="sticky-mobile-atc__btn" data-sticky-mobile-atc-button>
      {{- 'products.product.add_to_cart' | t -}}
    </button>
  </div>
  <script>
    (function () {
      var sticky = document.getElementById('StickyMobileATC-{{ section.id }}');
      if (!sticky) return;

      var mobileMedia = window.matchMedia('(max-width: 749px)');
      var stickyBtn = sticky.querySelector('[data-sticky-mobile-atc-button]');
      var stickyPrice = sticky.querySelector('[data-sticky-mobile-atc-price]');
      var stickySize = sticky.querySelector('[data-sticky-mobile-atc-size]');
      var stickyShipping = sticky.querySelector('[data-sticky-mobile-atc-shipping]');
      var sizeConversionMessage = document.getElementById('size-conversion-message');
      var mediaContainer =
        document.getElementById('GalleryViewer-{{ section.id }}') ||
        document.getElementById('MediaGallery-{{ section.id }}');
      var productForm = document.getElementById('product-form-{{ section.id }}');
      var atcBtn = document.getElementById('ProductSubmitButton-{{ section.id }}');
      var variantSelects = document.getElementById('variant-selects-{{ section.id }}');
      var priceContainer = document.getElementById('price-{{ section.id }}');
      var atcIsInViewport = true;
      var mediaIsInViewport = !!mediaContainer;
      var canShowSticky = true;
      var hasUserConfirmedSizeSelection = false;
      var hasUserConfirmedColorSelection = false;
      var highlightedGroup = null;
      var addToCartLabel = {{ 'products.product.add_to_cart' | t | json }};
      var chooseOptionsLabel = {{ 'products.product.choose_options' | t | json }};
      var chooseSizeLabel = {{ 'products.product.select_size' | t | json }};
      var chooseColorLabel = {{ 'products.product.select_color' | t | json }};
      var sizeRequiredMessageText = {{ 'products.product.size_required_message' | t | json }};
      var compareAtPriceTemplate = getProductPageCopyValue('compare_at_price') || 'Compare at __PRICE__';
      var selectedSizeTemplate = getProductPageCopyValue('selected_size_label') || 'Size: __SIZE__';

      if (!atcBtn && productForm) atcBtn = productForm.querySelector('[name="add"]');

      // CRO redesign May 2026: on matching-set products the standalone
      // ATC is hidden in favor of the bundle CTA. Repoint the sticky
      // bottom bar at the bundle's "Add Matching Set to Cart" button so
      // it (a) tracks the correct in-viewport target and (b) forwards
      // taps to the right action. Falls back to the original ATC when
      // there is no matching-set builder on the page.
      var infoContainer = document.getElementById('ProductInfo-{{ section.id }}');
      var isMatchingSet = infoContainer && infoContainer.getAttribute('data-has-matching-set') === 'true';
      var bundleSection = null;
      var matchingSetStickyState =
        window.DLMMatchingSetStickyState && window.DLMMatchingSetStickyState['{{ section.id }}']
          ? window.DLMMatchingSetStickyState['{{ section.id }}']
          : null;
      if (isMatchingSet) {
        var bundleCta = document.querySelector('[data-matching-set-add-button]');
        bundleSection = document.querySelector('[data-matching-set-builder]');
        if (bundleCta) atcBtn = bundleCta;
      }

      if (!atcBtn || !stickyBtn) return;

      function getProductPageCopyValue(key) {
        var copyMap = window.DLM_PRODUCT_PAGE_COPY;
        if (!copyMap || typeof copyMap !== 'object') return '';

        var locale = '';
        if (window.Shopify && typeof window.Shopify.locale === 'string') {
          locale = window.Shopify.locale;
        } else if (document.documentElement && document.documentElement.lang) {
          locale = document.documentElement.lang;
        }

        locale = String(locale || '').replace('_', '-').toLowerCase();
        var root = locale.split('-')[0];
        var candidates = [locale];
        if (root && root !== locale) candidates.push(root);
        if (root === 'pt') candidates.push('pt-BR', 'pt-PT');
        if (root === 'ro') candidates.push('ro', 'ro-RO');
        if (root === 'no') candidates.push('no', 'nb');
        candidates.push('en');

        var keys = Object.keys(copyMap);
        for (var index = 0; index < candidates.length; index += 1) {
          var candidate = candidates[index];
          for (var keyIndex = 0; keyIndex < keys.length; keyIndex += 1) {
            if (keys[keyIndex].toLowerCase() !== candidate.toLowerCase()) continue;
            return copyMap[keys[keyIndex]] && copyMap[keys[keyIndex]][key] ? copyMap[keys[keyIndex]][key] : '';
          }
        }

        return '';
      }

      function getButtonLabel() {
        // CRO redesign May 2026: on matching-set products the sticky
        // button forwards to the bundle CTA. Mirror its visible label
        // verbatim rather than the default "Add to cart" translation.
        if (isMatchingSet && atcBtn && atcBtn.hasAttribute('data-matching-set-add-button')) {
          var bundleText = (atcBtn.textContent || '').trim();
          return bundleText || 'Add Matching Set';
        }
        var labelNode = atcBtn.querySelector('span');
        if (!labelNode) return addToCartLabel;
        var labelText = labelNode.textContent ? labelNode.textContent.trim() : '';
        return labelText || addToCartLabel;
      }

      function setButtonText(button, text) {
        if (!button || !text) return;
        var labelNode = button.querySelector('span');
        if (!labelNode) return;
        var nextText = String(text).trim();
        if (!nextText) return;
        if (labelNode.textContent && labelNode.textContent.trim() === nextText) return;
        labelNode.textContent = nextText;
      }

      function getRenderedPriceState() {
        if (!priceContainer) return null;

        var priceNode = priceContainer.querySelector('.price');
        var currentPrice = priceNode && priceNode.dataset ? priceNode.dataset.priceCurrentText : '';
        var compareAtPrice = priceNode && priceNode.dataset ? priceNode.dataset.priceCompareText : '';
        var isOnSale = priceNode && priceNode.dataset ? priceNode.dataset.priceOnSale === 'true' : false;

        if (!currentPrice) {
          var salePrice = priceContainer.querySelector('.price__sale .price-item--sale');
          var regularPrice = priceContainer.querySelector('.price__regular .price-item--regular');
          var fallbackPrice = priceContainer.querySelector('.price-item');
          var activePrice = salePrice || regularPrice || fallbackPrice;
          currentPrice = activePrice && activePrice.textContent ? activePrice.textContent.replace(/\s+/g, ' ').trim() : '';
        }

        return {
          currentPrice: currentPrice || '',
          compareAtPrice: compareAtPrice || '',
          isOnSale: isOnSale,
        };
      }

      function syncBodyOffset(isVisible) {
        if (!document.body) return;

        if (isVisible) {
          document.body.classList.add('sticky-mobile-atc-visible');
          document.body.style.setProperty('--sticky-mobile-atc-offset', sticky.offsetHeight + 'px');
          return;
        }

        document.body.classList.remove('sticky-mobile-atc-visible');
        document.body.style.removeProperty('--sticky-mobile-atc-offset');
      }

      function toggleStickyVisibility() {
        var shouldShow = mobileMedia.matches && !atcIsInViewport && !mediaIsInViewport && canShowSticky;
        sticky.classList.toggle('visible', shouldShow);
        sticky.setAttribute('aria-hidden', shouldShow ? 'false' : 'true');
        syncBodyOffset(shouldShow);
      }

      function getOptionNameFromGroup(group) {
        if (!group) return '';

        var select = group.querySelector('select[name]');
        if (select && select.name) {
          var selectMatch = select.name.match(/^options\[(.+)\]$/);
          return (selectMatch ? selectMatch[1] : select.name).trim();
        }

        var radio = group.querySelector('input[type="radio"][name]');
        if (radio && radio.name) return radio.name.trim();

        var label = group.querySelector('legend, label.form__label, .form__label');
        if (!label || !label.textContent) return '';

        var labelText = label.textContent.replace(/\s+/g, ' ').trim();
        if (labelText.indexOf(':') > -1) labelText = labelText.split(':')[0];
        return labelText.trim();
      }

      function isSizeOptionGroup(group) {
        return /\bsize\b/.test(getOptionNameFromGroup(group).toLowerCase());
      }

      function isColorOptionGroup(group) {
        return /\bcolou?r\b/.test(getOptionNameFromGroup(group).toLowerCase());
      }

      function getSelectedOptionValue(group) {
        if (!group) return '';

        var select = group.querySelector('select');
        if (select) return (select.value || '').trim();

        var checkedRadio = group.querySelector('input[type="radio"]:checked');
        if (checkedRadio) return (checkedRadio.value || '').trim();

        return '';
      }

      function isInteractiveOptionGroup(group) {
        if (!group || group.hidden) return false;

        var computedStyle = window.getComputedStyle(group);
        return computedStyle.display !== 'none' && computedStyle.visibility !== 'hidden';
      }

      function markRequiredSelectionFromEvent(event) {
        if (!event || !event.target) return;

        var control = event.target.closest('select, input[type="radio"]');
        if (!control) return;

        var group = control.closest('.product-form__input');
        if (!group || !isInteractiveOptionGroup(group)) return;

        var selectedValue = getSelectedOptionValue(group) !== '';
        if (isSizeOptionGroup(group)) hasUserConfirmedSizeSelection = selectedValue;
        if (isColorOptionGroup(group)) hasUserConfirmedColorSelection = selectedValue;
      }

      function getSizeSelectionState() {
        var selectionState = {
          hasSizeOption: false,
          totalSizeOptions: 0,
          selectedSizeValues: [],
          sizeOptionGroups: [],
          isComplete: true,
          missingSizeOption: null,
          firstSizeOption: null,
        };

        if (!variantSelects) return selectionState;

        var optionGroups = Array.from(variantSelects.querySelectorAll('.product-form__input'));
        for (var i = 0; i < optionGroups.length; i += 1) {
          var group = optionGroups[i];
          if (!isInteractiveOptionGroup(group)) continue;
          if (!isSizeOptionGroup(group)) continue;

          selectionState.hasSizeOption = true;
          selectionState.totalSizeOptions += 1;
          selectionState.sizeOptionGroups.push(group);
          if (!selectionState.firstSizeOption) {
            selectionState.firstSizeOption = {
              group: group,
              focusTarget: group.querySelector('select, input[type="radio"]'),
              anchor: group.querySelector('label, legend, .form__label') || group,
            };
          }
          var selectedValue = getSelectedOptionValue(group);
          if (selectedValue !== '') {
            selectionState.selectedSizeValues.push(selectedValue);
          } else if (!selectionState.missingSizeOption) {
            selectionState.missingSizeOption = {
              group: group,
              focusTarget: group.querySelector('select, input[type="radio"]'),
              anchor: group.querySelector('label, legend, .form__label') || group,
            };
          }
        }

        selectionState.isComplete =
          !selectionState.hasSizeOption ||
          selectionState.selectedSizeValues.length === selectionState.totalSizeOptions;

        if (selectionState.isComplete) {
          selectionState.missingSizeOption = null;
        }

        return selectionState;
      }

      function getColorSelectionState() {
        var selectionState = {
          hasColorOption: false,
          totalColorOptions: 0,
          selectedColorValues: [],
          isComplete: true,
          missingColorOption: null,
          firstColorOption: null,
        };

        if (!variantSelects) return selectionState;

        var optionGroups = Array.from(variantSelects.querySelectorAll('.product-form__input'));
        for (var i = 0; i < optionGroups.length; i += 1) {
          var group = optionGroups[i];
          if (!isInteractiveOptionGroup(group)) continue;
          if (!isColorOptionGroup(group)) continue;

          selectionState.hasColorOption = true;
          selectionState.totalColorOptions += 1;
          if (!selectionState.firstColorOption) {
            selectionState.firstColorOption = {
              group: group,
              focusTarget: group.querySelector('select, input[type="radio"]'),
              anchor: group.querySelector('label, legend, .form__label') || group,
            };
          }
          var selectedValue = getSelectedOptionValue(group);
          if (selectedValue !== '') {
            selectionState.selectedColorValues.push(selectedValue);
          } else if (!selectionState.missingColorOption) {
            selectionState.missingColorOption = {
              group: group,
              focusTarget: group.querySelector('select, input[type="radio"]'),
              anchor: group.querySelector('label, legend, .form__label') || group,
            };
          }
        }

        selectionState.isComplete =
          !selectionState.hasColorOption ||
          selectionState.selectedColorValues.length === selectionState.totalColorOptions;

        if (selectionState.isComplete) {
          selectionState.missingColorOption = null;
        }

        return selectionState;
      }

      function getFirstMissingOption() {
        if (!variantSelects) return null;

        var optionGroups = Array.from(variantSelects.querySelectorAll('.product-form__input'));
        for (var i = 0; i < optionGroups.length; i += 1) {
          var group = optionGroups[i];
          if (!isInteractiveOptionGroup(group)) continue;
          var select = group.querySelector('select');
          if (select && select.value === '') {
            return {
              group: group,
              focusTarget: select,
              anchor: group.querySelector('label, legend, .form__label') || group,
            };
          }

          var radios = Array.from(group.querySelectorAll('input[type="radio"]'));
          if (radios.length && !group.querySelector('input[type="radio"]:checked')) {
            return {
              group: group,
              focusTarget: radios[0],
              anchor: group.querySelector('legend, .form__label') || group,
            };
          }
        }

        return null;
      }

      function highlightOptionGroup(group) {
        if (!group) return;

        if (highlightedGroup && highlightedGroup !== group) {
          highlightedGroup.classList.remove('sticky-option-target--highlight');
        }

        highlightedGroup = group;
        group.classList.add('sticky-option-target--highlight');

        window.setTimeout(function () {
          group.classList.remove('sticky-option-target--highlight');
          if (highlightedGroup === group) highlightedGroup = null;
        }, 1400);
      }

      function scrollToMissingOption(missingOption) {
        if (!missingOption) return;

        highlightOptionGroup(missingOption.group);

        var anchor = missingOption.anchor || missingOption.group || missingOption.focusTarget;
        if (anchor && anchor.getBoundingClientRect) {
          var offset = 112;
          var topPosition = window.scrollY + anchor.getBoundingClientRect().top - offset;
          window.scrollTo({ top: Math.max(topPosition, 0), behavior: 'smooth' });
        }

        if (missingOption.focusTarget && typeof missingOption.focusTarget.focus === 'function') {
          try {
            missingOption.focusTarget.focus({ preventScroll: true });
          } catch (e) {
            missingOption.focusTarget.focus();
          }
        }
      }

      function setSizePromptVisibility(group, shouldShow) {
        if (!group) return;

        var existingPrompt = group.querySelector('[data-size-required-message]');
        if (!existingPrompt) {
          existingPrompt = document.createElement('p');
          existingPrompt.className = 'product-form__size-required-message';
          existingPrompt.setAttribute('data-size-required-message', '');
          existingPrompt.setAttribute('role', 'status');
          existingPrompt.setAttribute('aria-live', 'polite');
          existingPrompt.textContent = sizeRequiredMessageText;
          group.appendChild(existingPrompt);
        }

        group.classList.toggle('product-form__input--size-required', shouldShow);
        if (shouldShow) {
          existingPrompt.removeAttribute('hidden');
          return;
        }

        existingPrompt.setAttribute('hidden', 'hidden');
      }

      function syncSizePrompt(sizeSelectionState, showPrompt) {
        var currentSizeState = sizeSelectionState || getSizeSelectionState();
        var targetGroup =
          showPrompt &&
          (currentSizeState.missingSizeOption
            ? currentSizeState.missingSizeOption.group
            : currentSizeState.firstSizeOption
              ? currentSizeState.firstSizeOption.group
              : null);

        currentSizeState.sizeOptionGroups.forEach(function (group) {
          setSizePromptVisibility(group, !!targetGroup && group === targetGroup);
        });

        if (sizeConversionMessage) {
          if (showPrompt) {
            sizeConversionMessage.textContent = sizeRequiredMessageText;
            sizeConversionMessage.removeAttribute('hidden');
          } else {
            sizeConversionMessage.textContent = '';
            sizeConversionMessage.setAttribute('hidden', 'hidden');
          }
        }

        if (!showPrompt) return;

        if (!atcBtn.hasAttribute('disabled')) {
          atcBtn.setAttribute('disabled', 'disabled');
        }
        setButtonText(atcBtn, chooseSizeLabel);
      }

      function syncStickyPrice() {
        if (!stickyPrice) return;

        var priceState = getRenderedPriceState();
        if (!priceState || !priceState.currentPrice) return;

        stickyPrice.textContent = priceState.currentPrice;
        if (priceState.isOnSale && priceState.compareAtPrice && priceState.compareAtPrice !== priceState.currentPrice) {
          stickyPrice.setAttribute(
            'aria-label',
            priceState.currentPrice + ', ' + compareAtPriceTemplate.replace('__PRICE__', priceState.compareAtPrice)
          );
          stickyPrice.title = priceState.compareAtPrice;
          return;
        }

        stickyPrice.removeAttribute('aria-label');
        stickyPrice.removeAttribute('title');
      }

      function syncStickyShipping(sizeIsConfirmed) {
        // CRO Step 6: hide the shipping reassurance once a size is
        // selected so the size chip can take its place without crowding
        // the bar. Before selection it's the most useful piece of info.
        if (!stickyShipping) return;
        if (sizeIsConfirmed) {
          stickyShipping.setAttribute('hidden', 'hidden');
        } else {
          stickyShipping.removeAttribute('hidden');
        }
      }

      function setMatchingStickyDetails() {
        if (!isMatchingSet) return false;

        var hasSelectedPieces = !!(matchingSetStickyState && matchingSetStickyState.isReady);
        if (stickyPrice) {
          stickyPrice.textContent = hasSelectedPieces
            ? matchingSetStickyState.pieceCountLabel || getButtonLabel()
            : getProductPageCopyValue('matching_set_heading') || 'Matching pieces';
          stickyPrice.removeAttribute('aria-label');
          stickyPrice.removeAttribute('title');
        }
        if (stickySize) {
          if (hasSelectedPieces && matchingSetStickyState.totalText) {
            stickySize.textContent = matchingSetStickyState.totalText;
            if (matchingSetStickyState.summaryText) {
              stickySize.title = matchingSetStickyState.summaryText;
              stickySize.setAttribute('aria-label', matchingSetStickyState.totalText + ': ' + matchingSetStickyState.summaryText);
            } else {
              stickySize.removeAttribute('title');
              stickySize.removeAttribute('aria-label');
            }
            stickySize.removeAttribute('hidden');
          } else {
            stickySize.textContent = '';
            stickySize.removeAttribute('title');
            stickySize.removeAttribute('aria-label');
            stickySize.setAttribute('hidden', 'hidden');
          }
        }
        if (stickyShipping) stickyShipping.setAttribute('hidden', 'hidden');
        return hasSelectedPieces;
      }

      function syncStickySize(sizeSelectionState) {
        if (!stickySize) return;

        var currentSizeState = sizeSelectionState || getSizeSelectionState();
        if (currentSizeState.hasSizeOption && (!hasUserConfirmedSizeSelection || !currentSizeState.isComplete)) {
          stickySize.textContent = '';
          stickySize.setAttribute('hidden', 'hidden');
          syncStickyShipping(false);
          return;
        }

        if (currentSizeState.hasSizeOption && currentSizeState.selectedSizeValues.length) {
          var formatter =
            window.DLMSizeLabelFormatter &&
            typeof window.DLMSizeLabelFormatter.formatSizeLabel === 'function'
              ? window.DLMSizeLabelFormatter.formatSizeLabel
              : null;
          var visibleSizeValues = currentSizeState.selectedSizeValues.map(function (value) {
            return formatter ? formatter(value) : value;
          });
          stickySize.textContent = selectedSizeTemplate.replace('__SIZE__', visibleSizeValues.join(' / '));
          stickySize.removeAttribute('hidden');
          syncStickyShipping(true);
          return;
        }

        stickySize.textContent = '';
        stickySize.setAttribute('hidden', 'hidden');
        syncStickyShipping(false);
      }

      function syncStickyState() {
        if (isMatchingSet && atcBtn && atcBtn.hasAttribute('data-matching-set-add-button')) {
          var matchingSetReady = setMatchingStickyDetails();
          canShowSticky = true;
          sticky.classList.toggle('requires-options', !matchingSetReady);
          stickyBtn.textContent = matchingSetReady ? getButtonLabel() : chooseOptionsLabel;
          stickyBtn.removeAttribute('disabled');
          toggleStickyVisibility();
          return;
        }

        var sizeSelectionState = getSizeSelectionState();
        var colorSelectionState = getColorSelectionState();
        var missingOption = getFirstMissingOption();
        var showSizePrompt =
          sizeSelectionState.hasSizeOption &&
          !sizeSelectionState.isComplete &&
          (!colorSelectionState.hasColorOption || hasUserConfirmedColorSelection);
        syncStickyPrice();
        syncStickySize(sizeSelectionState);
        syncSizePrompt(sizeSelectionState, showSizePrompt);

        if (sizeSelectionState.hasSizeOption && (!hasUserConfirmedSizeSelection || !sizeSelectionState.isComplete)) {
          canShowSticky = true;
          sticky.classList.add('requires-options');
          stickyBtn.textContent = chooseSizeLabel;
          stickyBtn.removeAttribute('disabled');
          toggleStickyVisibility();
          return;
        }

        if (colorSelectionState.hasColorOption && (!hasUserConfirmedColorSelection || !colorSelectionState.isComplete)) {
          canShowSticky = true;
          sticky.classList.add('requires-options');
          stickyBtn.textContent = chooseColorLabel;
          stickyBtn.removeAttribute('disabled');
          toggleStickyVisibility();
          return;
        }

        if (missingOption) {
          canShowSticky = true;
          sticky.classList.add('requires-options');
          stickyBtn.textContent = chooseOptionsLabel;
          stickyBtn.removeAttribute('disabled');
          toggleStickyVisibility();
          return;
        }

        canShowSticky = true;
        sticky.classList.remove('requires-options');
        stickyBtn.textContent = getButtonLabel();

        if (atcBtn.hasAttribute('disabled')) {
          stickyBtn.setAttribute('disabled', 'disabled');
        } else {
          stickyBtn.removeAttribute('disabled');
        }

        toggleStickyVisibility();
      }

      stickyBtn.addEventListener('click', function (event) {
        // CRO redesign May 2026: bundle products use their own per-card
        // size selection. The legacy size/color/option-prompt gating
        // below relies on the main variant-selects, which is irrelevant
        // for the bundle flow — bypass it and forward straight to the
        // bundle CTA (which has its own disabled-until-valid state).
        if (isMatchingSet && atcBtn && atcBtn.hasAttribute('data-matching-set-add-button')) {
          if (!matchingSetStickyState || !matchingSetStickyState.isReady || atcBtn.hasAttribute('disabled')) {
            event.preventDefault();
            // Scroll the bundle into view so the shopper knows what to
            // pick. The bundle CTA itself is the call-out.
            if (bundleSection && typeof bundleSection.scrollIntoView === 'function') {
              bundleSection.scrollIntoView({ behavior: 'smooth', block: 'center' });
            }
            return;
          }
          if (bundleSection && typeof bundleSection.getBoundingClientRect === 'function') {
            var bundleTop = bundleSection.getBoundingClientRect().top + window.scrollY - 120;
            window.DLMCartDrawerOpenScrollY = Math.max(0, bundleTop);
            window.scrollTo({ top: window.DLMCartDrawerOpenScrollY, behavior: 'auto' });
          }
          atcBtn.click();
          return;
        }

        var sizeSelectionState = getSizeSelectionState();
        if (sizeSelectionState.hasSizeOption && (!hasUserConfirmedSizeSelection || !sizeSelectionState.isComplete)) {
          event.preventDefault();
          syncSizePrompt(sizeSelectionState, true);
          scrollToMissingOption(
            sizeSelectionState.missingSizeOption || sizeSelectionState.firstSizeOption || getFirstMissingOption()
          );
          return;
        }

        var colorSelectionState = getColorSelectionState();
        if (colorSelectionState.hasColorOption && (!hasUserConfirmedColorSelection || !colorSelectionState.isComplete)) {
          event.preventDefault();
          scrollToMissingOption(
            colorSelectionState.missingColorOption || colorSelectionState.firstColorOption || getFirstMissingOption()
          );
          return;
        }

        var missingOption = getFirstMissingOption();

        if (missingOption) {
          event.preventDefault();
          scrollToMissingOption(missingOption);
          return;
        }

        if (atcBtn.hasAttribute('disabled')) return;
        atcBtn.click();
      });

      var visibilityObserver = new IntersectionObserver(
        function (entries) {
          entries.forEach(function (entry) {
            atcIsInViewport = entry.isIntersecting;
            toggleStickyVisibility();
          });
        },
        { threshold: 0 }
      );
      visibilityObserver.observe(atcBtn);

      if (mediaContainer) {
        var mediaObserver = new IntersectionObserver(
          function (entries) {
            entries.forEach(function (entry) {
              mediaIsInViewport = entry.isIntersecting;
              toggleStickyVisibility();
            });
          },
          { threshold: 0 }
        );
        mediaObserver.observe(mediaContainer);
      }

      if (variantSelects) {
        variantSelects.addEventListener('change', function (event) {
          markRequiredSelectionFromEvent(event);
          window.requestAnimationFrame(syncStickyState);
        });
        variantSelects.addEventListener('click', function (event) {
          markRequiredSelectionFromEvent(event);
          window.requestAnimationFrame(syncStickyState);
        });
      }

      var atcObserver = new MutationObserver(syncStickyState);
      atcObserver.observe(atcBtn, {
        attributes: true,
        attributeFilter: ['disabled'],
        childList: true,
        subtree: true,
        characterData: true,
      });

      if (priceContainer) {
        var priceObserver = new MutationObserver(syncStickyPrice);
        priceObserver.observe(priceContainer, {
          childList: true,
          subtree: true,
          characterData: true,
        });
      }

      if (isMatchingSet) {
        document.addEventListener('dlm:matching-set-summary', function (event) {
          if (!event || !event.detail || event.detail.sectionId !== '{{ section.id }}') return;
          matchingSetStickyState = event.detail;
          syncStickyState();
        });
      }

      function handleViewportChange() {
        if (!mobileMedia.matches) sticky.classList.remove('visible');
        syncStickyState();
      }

      if (typeof mobileMedia.addEventListener === 'function') {
        mobileMedia.addEventListener('change', handleViewportChange);
      } else if (typeof mobileMedia.addListener === 'function') {
        mobileMedia.addListener(handleViewportChange);
      }

      syncStickyState();
    })();
  </script>
{%- endif -%}

<script>
  (function () {
    function currentLocale() {
      var locale = '';
      if (window.Shopify && typeof window.Shopify.locale === 'string') {
        locale = window.Shopify.locale;
      } else if (document.documentElement && document.documentElement.lang) {
        locale = document.documentElement.lang;
      }
      return String(locale || '').replace('_', '-').trim();
    }

    function localeCopy() {
      var copyMap = window.DLM_PRODUCT_PAGE_COPY;
      if (!copyMap || typeof copyMap !== 'object') return null;

      var locale = currentLocale().toLowerCase();
      var root = locale.split('-')[0];
      var candidates = [locale];
      if (root && root !== locale) candidates.push(root);
      if (root === 'pt') candidates.push('pt-BR', 'pt-PT');
      if (root === 'ro') candidates.push('ro', 'ro-RO');
      if (root === 'no') candidates.push('no', 'nb');

      var keys = Object.keys(copyMap);
      for (var i = 0; i < candidates.length; i += 1) {
        var candidate = candidates[i];
        for (var j = 0; j < keys.length; j += 1) {
          if (keys[j].toLowerCase() === candidate.toLowerCase()) {
            return copyMap[keys[j]];
          }
        }
      }

      return copyMap.en || null;
    }

    var copy = localeCopy();
    if (!copy) return;
    var desktopUxWrapper = document.querySelector('[data-product-desktop-ux]');
    var isGoldenDaisyPdp = desktopUxWrapper && desktopUxWrapper.getAttribute('data-product-handle') === 'golden-daisy-mommy-and-me-set';
    var localeRoot = currentLocale().toLowerCase().split('-')[0];
    var customerPhotosByLocale = {
      cs: 'Fotky zákazníků',
      da: 'Kundebilleder',
      de: 'Kundenfotos',
      el: 'Φωτογραφίες πελατών',
      es: 'Fotos de clientes',
      fr: 'Photos clients',
      it: 'Foto dei clienti',
      nl: "Foto's van klanten",
      pl: 'Zdjęcia klientów',
      pt: 'Fotos de clientes',
      ro: 'Fotografii de la clienți',
      sv: 'Kundfoton'
    };
    var customerPhotosHeading = copy.customer_photos_heading || customerPhotosByLocale[localeRoot] || 'Customer photos';
    var matchingSetRuntimeCopy = copy.matching_set_copy;
    if (isGoldenDaisyPdp && (!localeRoot || localeRoot === 'en')) {
      matchingSetRuntimeCopy = 'Pair the yellow daisy top with the ivory floral pants for a complete mommy-and-me outfit.';
    }

    var translations = {
      'Build your matching set': copy.matching_set_heading,
      ['Choose the family sizes you want and add them together from one product page.']: matchingSetRuntimeCopy,
      ['Add one piece per family member. Sizes are independent and each piece is sold separately.']: matchingSetRuntimeCopy,
      // CRO Tier 1 (May 2026): new conversion-friendly EN default — must
      // still get swapped to the localized matching_set_copy for non-EN
      // shoppers, so we add it as another runtime translation key.
      ['Add matching family sizes below — each selection is sold separately.']: matchingSetRuntimeCopy,
      ['Pair the yellow daisy top with the ivory floral pants for a complete mommy-and-me outfit.']: matchingSetRuntimeCopy,
      ['Choose at least one family size to add your set.']: copy.matching_set_empty,
      ['Choose at least one size to add your set.']: copy.matching_set_empty,
      'Add selected pieces': copy.matching_set_add,
      'Add selected pieces to cart': copy.matching_set_add,
      'Add matching pieces': copy.matching_set_add,
      'Add matching pieces to cart': copy.matching_set_add,
      // CRO redesign May 2026: new bundle CTA copy.
      'Add Matching Set to Cart': copy.matching_set_add,
      'Compare family sizes': copy.grouped_size_guide_label,
      'Compare all sizes': copy.compare_size_guide_label,
      'Size guide & fit': copy.single_size_guide_label,
      'Your size details': copy.selected_size_guide_label,
      'Open the full chart below to compare nearby sizes.': copy.size_guide_compare_hint,
      'Customer reviews': copy.reviews_heading,
      'Customer photo reviews': copy.photo_heading,
      'Customer photos': customerPhotosHeading,
      'Jump to reviews': copy.jump_to_reviews,
      'Secure Checkout': copy.secure_checkout,
      ['30-Day ' + 'Returns']: copy.returns,
      ['Trusted ' + 'since 2016']: copy.trusted_since,
      'Need help? We typically reply within one business day.': copy.assistance_note,
      ['Shipping ' + 'Worldwide']: copy.shipping_title,
      'Shipping options': copy.free_shipping_label,
      'Est. Delivery': copy.estimated_delivery,
      'Delivery details at checkout': copy.estimated_delivery,
      'Want it faster? Spend $100+ and get': copy.faster_shipping_prefix,
      'Express shipping': copy.free_premium_shipping,
      'Standard shipping included': copy.free_shipping_all_orders,
      'Return Policy': copy.return_policy_title,
      ['We gladly accept returns within 30 days of ' + 'purchase.']: copy.return_policy_line_1,
      ['Items should be in their original condition and packaging to qualify for a full refund. Please note that buyers are responsible for return shipping costs.']: copy.return_policy_line_2,
      ["If an item is returned damaged, used, or missing parts, we may deduct a portion of the refund to cover any loss in the item's value."]: copy.return_policy_line_3,
      ['To ensure a smooth return process, kindly return items in the same condition as received, including all packaging and original contents.']: copy.return_policy_line_4,
      'Shopping Security': copy.shopping_security_title,
      'Safe Payment Options': copy.safe_payment_options_title,
      'We accept all major credit and debit cards. Your card details are secure and never shared with our partners. You can easily manage your saved cards anytime. For any transaction inquiries, please contact your card issuer.': copy.safe_payment_description,
      'Shipping Support': copy.secure_logistics_title,
      'If a package is damaged or lost in transit, contact us so we can help review the shipment.': copy.secure_logistics_line_1,
      'Use your order tracking link for the latest carrier updates.': copy.secure_logistics_line_2,
      'Secure Privacy': copy.secure_privacy_title,
      'Protecting your privacy is important to us! Please be assured that your information will be kept secured and uncompromised. We do not sell your personal information for money and will only use your information in accordance with our privacy and cookie policy to provide and improve our services to you.': copy.secure_privacy_description,
      'Complete the Look': copy.complete_the_look,
      'Similar styles': copy.similar_styles,
      'Browse similar styles': copy.browse_similar_styles,
      'Use this collection to compare a few close matches before you go back to shopping.': copy.compare_collection_copy,
      'Popular with Families': copy.popular_with_families,
      'Recently Viewed': copy.recently_viewed,
      'CUSTOMER REVIEWS': copy.review_widget_heading_uppercase,
      'Customer Reviews': copy.review_widget_heading,
      'Be the first to write a review': copy.review_widget_empty,
      'Write a review': copy.review_widget_write_review,
      'Write a Review': copy.review_widget_write_review_title,
    };

    function normalize(text) {
      return text ? text.replace(/\s+/g, ' ').trim() : '';
    }

    function replaceWithContext(template, context) {
      return String(template || '').replace(/__CONTEXT__/g, context || '');
    }

    function translateTextNodes(root) {
      if (!root) return;
      var walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
      var node;
      while ((node = walker.nextNode())) {
        var normalized = normalize(node.nodeValue);
        if (!normalized) continue;
        if (Object.prototype.hasOwnProperty.call(translations, normalized)) {
          node.nodeValue = node.nodeValue.replace(normalized, translations[normalized]);
        }
      }
    }

    function applyAttributeTranslations() {
      var wrapper = desktopUxWrapper || document.querySelector('[data-product-desktop-ux]');
      if (wrapper) {
        wrapper.setAttribute('data-matching-set-copy', matchingSetRuntimeCopy);
        wrapper.setAttribute('data-matching-set-empty', copy.matching_set_empty);
        wrapper.setAttribute('data-matching-set-add', copy.matching_set_add);
        wrapper.setAttribute('data-matching-set-success', copy.matching_set_success);
        wrapper.setAttribute('data-matching-set-error', copy.matching_set_error);
        wrapper.setAttribute('data-size-guide-single-label', copy.single_size_guide_label);
        wrapper.setAttribute('data-size-guide-grouped-label', copy.grouped_size_guide_label);
        wrapper.setAttribute('data-size-guide-compare-label', copy.compare_size_guide_label);
        wrapper.setAttribute('data-size-guide-selected-label', copy.selected_size_guide_label);
        wrapper.setAttribute('data-size-guide-compare-hint', copy.size_guide_compare_hint);
        wrapper.setAttribute('data-size-guide-unit-toggle-label', copy.size_guide_unit_toggle_label);
        wrapper.setAttribute('data-customer-photos-label', customerPhotosHeading);
      }

      document.querySelectorAll('[data-back-to-results]').forEach(function (control) {
        control.setAttribute('data-back-to-results-label-default', copy.back_to_results);
        control.setAttribute('data-back-to-results-template', copy.back_to_context);
        control.setAttribute('data-back-to-search-results-label', copy.back_to_search_results);
      });

      document.querySelectorAll('.product__trust-strip').forEach(function (strip) {
        strip.setAttribute('aria-label', copy.secure_checkout);
      });
    }

    function applyContextTranslations() {
      document.querySelectorAll('[data-back-to-results-label]').forEach(function (node) {
        var text = normalize(node.textContent);
        if (text === 'Back to results') {
          node.textContent = copy.back_to_results;
          return;
        }
        if (text === 'Back to Family Sets') {
          node.textContent = copy.back_to_family_sets;
          return;
        }
        if (text.indexOf('Back to ') === 0) {
          node.textContent = replaceWithContext(copy.back_to_context, text.slice('Back to '.length));
        }
      });

      document.querySelectorAll('.buy-box-similar-styles__title').forEach(function (node) {
        var text = normalize(node.textContent);
        if (text === 'Browse similar styles') {
          node.textContent = copy.browse_similar_styles;
          return;
        }
        if (text.indexOf('Browse more from ') === 0) {
          node.textContent = replaceWithContext(copy.browse_more_from, text.slice('Browse more from '.length));
        }
      });

      document.querySelectorAll('.product-breadcrumb__browse-link').forEach(function (link) {
        var text = normalize(link.textContent);
        if (text === 'View similar styles') {
          link.textContent = copy.view_similar_styles;
        }

        ['aria-label', 'title'].forEach(function (attribute) {
          var value = normalize(link.getAttribute(attribute));
          if (!value) return;
          if (value.indexOf('View similar styles in ') === 0) {
            link.setAttribute(attribute, replaceWithContext(copy.view_similar_styles_in, value.slice('View similar styles in '.length)));
          } else if (value === 'View similar styles') {
            link.setAttribute(attribute, copy.view_similar_styles);
          }
        });
      });
    }

    function applyProductTranslations() {
      applyAttributeTranslations();
      translateTextNodes(document.body);
      applyContextTranslations();

      document.querySelectorAll('[class*="jdgm"]').forEach(function (element) {
        translateTextNodes(element);
      });
    }

    var scheduled = false;
    function scheduleApply() {
      if (scheduled) return;
      scheduled = true;
      window.requestAnimationFrame(function () {
        scheduled = false;
        applyProductTranslations();
      });
    }

    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', scheduleApply);
    } else {
      scheduleApply();
    }

    var observer = new MutationObserver(scheduleApply);
    observer.observe(document.body, {
      childList: true,
      subtree: true,
      characterData: true,
    });
  })();
</script>


